17: const DEFAULT_NAMES = ['Alex','Sam','Jordan','Taylor'];
18: function readStore(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value===null?fallback:value}catch{return fallback}}
19: function makeParty(name,players=[]){return{id:`party-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,name,players:[...players],scores:{},stats:{},history:[]}}
20: const savedPlayers=readStore('imposter.players',[...DEFAULT_NAMES]);
21: const savedScores=readStore('imposter.scores',{});
22: const savedSettings=readStore('imposter.settings',{});
23: const savedParties=readStore('imposter.parties',[]);
24: const parties=Array.isArray(savedParties)?savedParties.filter(p=>p&&p.id&&Array.isArray(p.players)).map(p=>({...p,scores:p.scores||{},stats:p.stats||{},history:Array.isArray(p.history)?p.history:[]})):[];
25: if(!parties.length)parties.push({...makeParty('My Party',savedPlayers),scores:savedScores});
26: const selectedParty=parties.find(p=>p.id===localStorage.getItem('imposter.activeParty'))||parties[0];
27: const state = {
28:   parties,activePartyId:selectedParty.id,players:selectedParty.players,scores:selectedParty.scores,
29:   settings:{imposters:1,timer:60,guess:true,categories:['Random Mix'],hints:false,typedClues:true,...savedSettings},
