155: function generateHint(word,category){
156:  const rules=HINT_RULES[category];if(!rules)return '';
157:  const key=word.toLowerCase();
158:  const group=rules.groups.find(rule=>rule.words.split('|').includes(key));
159:  const choices=group?group.hints:rules.fallback;
160:  const index=[...key].reduce((sum,char)=>sum+char.charCodeAt(0),0)%choices.length;
161:  const hint=choices[index];
162:  const hintWords=hint.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),secretWords=key.split(/[^a-z0-9]+/).filter(Boolean);
163:  const revealsWord=secretWords.length&&hintWords.some((_,i)=>secretWords.every((part,j)=>hintWords[i+j]===part));
164:  return revealsWord?rules.fallback[(index+1)%rules.fallback.length]:hint;
165: }
